var c="static-v1";self.addEventListener("install",e=>{e.waitUntil((async()=>{try{let s=await fetch("cache.json");if(!s.ok)throw new Error(`HTTP error status: ${s.status}`);let r=(await s.json()).map(a=>new URL(a,self.location.href).href),n=await caches.open(c);for(let a of r)try{await n.add(a)}catch{}}catch{self.skipWaiting()}})())});self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(s=>Promise.all(s.filter(t=>t!==c).map(t=>caches.delete(t)))).then(()=>self.clients.claim()))});self.addEventListener("fetch",e=>{e.request.method!=="GET"||e.request.url.startsWith("chrome-extension://")||e.respondWith((async()=>{try{let s=await caches.match(e.request);if(s)return s;let t=await fetch(e.request);return(t.ok&&t.status!==206&&t.type==="basic"||t.type==="cors")&&(await caches.open(c)).put(e.request,t.clone()),t}catch{return await caches.match(e.request)||Response.error()}})())});self.addEventListener("error",e=>{});self.addEventListener("unhandledrejection",e=>{});
